# Look at row differences from the background pattern
for r in range(height):
    row_vals = []
    for c in range(width):
        bg = expected_value(r, c)
        diff = 'X' if grid[r, c] != bg else '.'
        row_vals.append(diff)
    print(f"Row {r}: {''.join(row_vals)}")

